package io.lumine.mythic.lib.api.crafting.ingredients;
import net.minecraft.item.ItemStack; import java.util.*;
public class MythicRecipeInventory implements Cloneable { private final List<List<ItemStack>> rows=new ArrayList<>(); public MythicRecipeInventory(){} public int getHeight(){return rows.size();} public int getWidth(){int w=0;for(List<ItemStack> r:rows)w=Math.max(w,r.size());return w;} public ItemStack getItemAt(int x,int y){if(y<0||y>=rows.size())return ItemStack.EMPTY;List<ItemStack> r=rows.get(y);return x<0||x>=r.size()?ItemStack.EMPTY:r.get(x);} public boolean setItemAt(int x,int y,ItemStack s){if(x<0||y<0)return false;while(rows.size()<=y)rows.add(new ArrayList<>());List<ItemStack> r=rows.get(y);while(r.size()<=x)r.add(ItemStack.EMPTY);r.set(x,s==null?ItemStack.EMPTY:s.copy());return true;} public void addRow(ItemStack... items){List<ItemStack> r=new ArrayList<>();for(ItemStack s:items)r.add(s==null?ItemStack.EMPTY:s.copy());rows.add(r);} public void setRow(int y,ItemStack... items){while(rows.size()<=y)rows.add(new ArrayList<>());List<ItemStack> r=new ArrayList<>();for(ItemStack s:items)r.add(s==null?ItemStack.EMPTY:s.copy());rows.set(y,r);} public void clearContents(){rows.clear();} public void clean(){while(!rows.isEmpty()&&rows.get(rows.size()-1).stream().allMatch(ItemStack::isEmpty))rows.remove(rows.size()-1);} public MythicRecipeInventory clone(){MythicRecipeInventory c=new MythicRecipeInventory();for(List<ItemStack> r:rows)c.addRow(r.stream().map(ItemStack::copy).toArray(ItemStack[]::new));return c;} public ItemStack getFirst(){for(List<ItemStack> r:rows)for(ItemStack s:r)if(!s.isEmpty())return s;return ItemStack.EMPTY;} public ArrayList<String> toStrings(String prefix){ArrayList<String> out=new ArrayList<>();for(int y=0;y<getHeight();y++)for(int x=0;x<getWidth();x++){ItemStack s=getItemAt(x,y);if(!s.isEmpty())out.add((prefix==null?"":prefix)+x+","+y+"="+s);}return out;} }
